insert into public.visits (id, restaurant_id, user_id, visited_at, food_rating, stress_level, note, photo_url, created_at) values
  (md5('rj-seed-v-seed-1')::uuid, 'r-olive-ember', '00000000-0000-4000-8000-000000000001', '2026-09-21T18:00:00.000Z', 5, 2, 'Sat in the garden. Our 4-year-old ate three flatbreads. Staff brought crayons without asking.', null, '2026-09-21T18:00:00.000Z'),
  (md5('rj-seed-v-seed-2')::uuid, 'r-olive-ember', '00000000-0000-4000-8000-000000000002', '2026-10-02T18:00:00.000Z', 4, 2, 'Plenty of room for the stroller by the side door.', null, '2026-10-02T18:00:00.000Z'),
  (md5('rj-seed-v-seed-3')::uuid, 'r-little-sprout', '00000000-0000-4000-8000-000000000004', '2026-10-02T18:00:00.000Z', 4, 1, 'Fast. Food hit the table in 8 minutes, which is the only metric that matters.', null, '2026-10-02T18:00:00.000Z'),
  (md5('rj-seed-v-seed-4')::uuid, 'r-little-sprout', '00000000-0000-4000-8000-000000000005', '2026-09-16T18:00:00.000Z', 4, 2, 'Loud, but nobody notices a crying baby here. Changing table in the family restroom is clean.', null, '2026-09-16T18:00:00.000Z'),
  (md5('rj-seed-v-seed-5')::uuid, 'r-court-dumpling', '00000000-0000-4000-8000-000000000003', '2026-08-30T18:00:00.000Z', 5, 3, 'Great dumplings, tight squeeze with twins in a double stroller. Better with a carrier.', null, '2026-08-30T18:00:00.000Z'),
  (md5('rj-seed-v-seed-6')::uuid, 'r-marigold', '00000000-0000-4000-8000-000000000002', '2026-09-14T18:00:00.000Z', 4, 3, 'No high chairs the night we went; they offered booster seats instead.', null, '2026-09-14T18:00:00.000Z'),
  (md5('rj-seed-v-seed-7')::uuid, 'r-kettle-crumb', '00000000-0000-4000-8000-000000000001', '2026-09-28T18:00:00.000Z', 5, 1, 'The calmest brunch we have had in years. Corner booth is perfect for nursing.', null, '2026-09-28T18:00:00.000Z'),
  (md5('rj-seed-v-seed-8')::uuid, 'r-kettle-crumb', '00000000-0000-4000-8000-000000000005', '2026-09-07T18:00:00.000Z', 4, 2, 'Weekend lines get long. Go before 9.', null, '2026-09-07T18:00:00.000Z'),
  (md5('rj-seed-v-seed-9')::uuid, 'r-fifth-flour', '00000000-0000-4000-8000-000000000003', '2026-09-30T18:00:00.000Z', 4, 1, 'Wide aisles, soup in a to-go cup for the toddler. Zero stress.', null, '2026-09-30T18:00:00.000Z'),
  (md5('rj-seed-v-seed-10')::uuid, 'r-seventh-noodle', '00000000-0000-4000-8000-000000000004', '2026-09-05T18:00:00.000Z', 4, 2, 'Kids bowls are the right size. Stroller parking is outside only.', null, '2026-09-05T18:00:00.000Z'),
  (md5('rj-seed-v-seed-11')::uuid, 'r-brownstone-burger', '00000000-0000-4000-8000-000000000002', '2026-10-04T18:00:00.000Z', 3, 1, 'Not fancy, but the kids menu came with milkshakes. Win.', null, '2026-10-04T18:00:00.000Z'),
  (md5('rj-seed-v-seed-12')::uuid, 'r-brownstone-burger', '00000000-0000-4000-8000-000000000001', '2026-09-19T18:00:00.000Z', 4, 2, null, null, '2026-09-19T18:00:00.000Z'),
  (md5('rj-seed-v-seed-13')::uuid, 'r-saffron-table', '00000000-0000-4000-8000-000000000003', '2026-08-12T18:00:00.000Z', 5, 2, 'Quiet room and the owner made a plain rice and dal for our picky eater.', null, '2026-08-12T18:00:00.000Z'),
  (md5('rj-seed-v-seed-14')::uuid, 'r-lantern-room', '00000000-0000-4000-8000-000000000004', '2026-07-19T18:00:00.000Z', 5, 4, 'Delicious but we were the only table with kids. Not relaxed.', null, '2026-07-19T18:00:00.000Z'),
  (md5('rj-seed-v-seed-15')::uuid, 'r-prospect-pie', '00000000-0000-4000-8000-000000000005', '2026-09-09T18:00:00.000Z', 4, 2, 'Right near the park so a good post-playground stop.', null, '2026-09-09T18:00:00.000Z'),
  (md5('rj-seed-v-seed-16')::uuid, 'r-atlantic-mezze', '00000000-0000-4000-8000-000000000001', '2026-09-18T18:00:00.000Z', 5, 2, 'Perfect for sharing. Our 2-year-old lived on pita and hummus.', null, '2026-09-18T18:00:00.000Z'),
  (md5('rj-seed-v-seed-17')::uuid, 'r-maison-petit', '00000000-0000-4000-8000-000000000002', '2026-06-22T18:00:00.000Z', 4, 4, 'Lovely at lunch, but tables are close together and the stroller had nowhere to go.', null, '2026-06-22T18:00:00.000Z'),
  (md5('rj-seed-v-seed-18')::uuid, 'r-hoyt-bagels', '00000000-0000-4000-8000-000000000004', '2026-08-02T18:00:00.000Z', 4, 3, 'Take it to the playground. Not a sit-down spot.', null, '2026-08-02T18:00:00.000Z'),
  (md5('rj-seed-v-seed-19')::uuid, 'r-cobble-cantina', '00000000-0000-4000-8000-000000000003', '2026-10-01T18:00:00.000Z', 4, 1, 'Booths are huge and the chips come out before we sit.', null, '2026-10-01T18:00:00.000Z'),
  (md5('rj-seed-v-seed-20')::uuid, 'r-cobble-cantina', '00000000-0000-4000-8000-000000000002', '2026-09-11T18:00:00.000Z', 4, 2, null, null, '2026-09-11T18:00:00.000Z'),
  (md5('rj-seed-v-seed-21')::uuid, 'r-basil-brine', '00000000-0000-4000-8000-000000000001', '2026-09-12T18:00:00.000Z', 5, 3, 'Half-portion pasta is great. They do not take walk-ins on weekends, so book ahead.', null, '2026-09-12T18:00:00.000Z'),
  (md5('rj-seed-v-seed-22')::uuid, 'r-amsterdam-diner', '00000000-0000-4000-8000-000000000005', '2026-10-05T18:00:00.000Z', 4, 1, 'Open super late which saved us after a long afternoon. Big booths.', null, '2026-10-05T18:00:00.000Z'),
  (md5('rj-seed-v-seed-23')::uuid, 'r-amsterdam-diner', '00000000-0000-4000-8000-000000000004', '2026-09-27T18:00:00.000Z', 3, 2, 'Fast, friendly, kids menu comes with a free dessert.', null, '2026-09-27T18:00:00.000Z'),
  (md5('rj-seed-v-seed-24')::uuid, 'r-columbus-thai', '00000000-0000-4000-8000-000000000003', '2026-09-02T18:00:00.000Z', 4, 2, 'Quiet enough to hear each other. They split a dish for the twins without being asked.', null, '2026-09-02T18:00:00.000Z'),
  (md5('rj-seed-v-seed-25')::uuid, 'r-riverside-sushi', '00000000-0000-4000-8000-000000000002', '2026-08-21T18:00:00.000Z', 4, 2, 'Calm room, but no high chairs.', null, '2026-08-21T18:00:00.000Z'),
  (md5('rj-seed-v-seed-26')::uuid, 'r-broadway-bistro', '00000000-0000-4000-8000-000000000001', '2026-09-26T18:00:00.000Z', 4, 2, 'Changing table is in the main restroom. Lovely staff.', null, '2026-09-26T18:00:00.000Z'),
  (md5('rj-seed-v-seed-27')::uuid, 'r-bella-nonna', '00000000-0000-4000-8000-000000000004', '2026-10-03T18:00:00.000Z', 5, 2, 'Our toddler got a free dough ball to play with. The whole room smiles at kids here.', null, '2026-10-03T18:00:00.000Z'),
  (md5('rj-seed-v-seed-28')::uuid, 'r-west-end-falafel', '00000000-0000-4000-8000-000000000005', '2026-07-30T18:00:00.000Z', 3, 3, 'Fine for a quick lunch, no real seating for a stroller.', null, '2026-07-30T18:00:00.000Z'),
  (md5('rj-seed-v-seed-29')::uuid, 'r-hudson-brasserie', '00000000-0000-4000-8000-000000000003', '2026-06-04T18:00:00.000Z', 4, 3, 'Beautiful, but wait times for food were long for the little ones.', null, '2026-06-04T18:00:00.000Z'),
  (md5('rj-seed-v-seed-30')::uuid, 'r-duane-dough', '00000000-0000-4000-8000-000000000002', '2026-09-24T18:00:00.000Z', 5, 1, 'Open kitchen kept our 3-year-old entertained for the entire meal.', null, '2026-09-24T18:00:00.000Z'),
  (md5('rj-seed-v-seed-31')::uuid, 'r-franklin-fields', '00000000-0000-4000-8000-000000000001', '2026-08-27T18:00:00.000Z', 5, 1, 'Early seating is basically a family dinner club. Super relaxed.', null, '2026-08-27T18:00:00.000Z')
insert into public.visit_attribute_confirmations (visit_id, key, value) values
  (md5('rj-seed-v-seed-2')::uuid, 'strollerFriendly', 'true'::jsonb)
